// First-party classic worker host. MediaPipe 0.10.32 uses importScripts.
// Entry is generated by Vite; only same-origin source/built worker is accepted.
const entry = new URL(new URL(self.location.href).searchParams.get('entry'));
if (
  entry.origin !== self.location.origin ||
  !(
    /^\/src\/vision\/vision\.worker\.ts$/.test(entry.pathname) ||
    /^\/assets\/vision\.worker-[\w-]+\.js$/.test(entry.pathname)
  )
)
  throw new Error('Invalid vision worker entry');
// Preserve only one INIT before module loading; never retain image frames.
let initial;
self.onmessage = (event) => {
  const data = event.data;
  const sessionId =
    typeof data?.sessionId === 'string' ? data.sessionId : 'invalid';
  if (data?.type === 'DISPOSE' && data.schemaVersion === 1) {
    initial = undefined;
    self.postMessage({ type: 'DISPOSED', schemaVersion: 1, sessionId });
  } else if (!initial && data?.type === 'INIT') initial = event;
  else {
    if (data?.bitmap instanceof ImageBitmap) data.bitmap.close();
    self.postMessage({
      type: 'ERROR',
      schemaVersion: 1,
      sessionId,
      error: {
        schemaVersion: 1,
        id: 'bootstrap-protocol',
        code: 'E-VIS-006',
        module: 'M04',
        severity: 'ERROR',
        recoverable: false,
        retryPolicy: 'NONE',
        messageKey: 'vision.protocolInvalid',
        atMs: performance.now(),
        sessionId,
      },
    });
  }
};
import(entry.href)
  .then(() => {
    const receive = self.onmessage;
    if (initial) receive(initial);
    initial = undefined;
  })
  .catch((error) => {
    throw error;
  });
